### 2. **FlattenDesign Connection Resolution - [compose/js/index.ts](compose/js/index.ts)**

**Lines [6587-6700](compose/js/index.ts#L6587-L6700):**

```typescript
export const flattenDesign = (kit: Kit, designId: string): DesignChange => {
  const design = findDesignInKit(kit, designId);
  if (!design) {
    throw new Error(`Design ${designId} not found in kit ${kit.name}`);
  }

  const types = kit.types ?? [];
  if (!design.pieces || design.pieces.length === 0) return { forward: {}, backward: {} };

  // Build type dictionary for fast lookup
  const typesDict: { [key: string]: Type } = {};
  types.forEach((t) => {
    typesDict[t.guid] = t;
  });

  const getType = (typeGuid: string): Type | undefined => {
    return typesDict[typeGuid];
  };

  // Connector resolution with inheritance support
  const getConnector = (type: Type | undefined, connectorGuid: string | undefined): Connector | undefined => {
    if (!type) return undefined;
    if (!connectorGuid) {
      if (type.connectors && type.connectors.length > 0) {
        return type.connectors[0];  // Default to first
      }
      if (type.parent?.guid) {
        const parentType = getType(type.parent.guid);
        return getConnector(parentType, connectorGuid);  // Walk up hierarchy
      }
      return undefined;
    }
    // ... specific connector lookup
  };

  const flatDesign: Design = JSON.parse(JSON.stringify(design));
  if (!flatDesign.pieces) flatDesign.pieces = [];

  // ⚠️ CRITICAL: Build piece map for connection validation
  const piecePlanes: { [pieceGuid: string]: Plane } = {};
  const pieceMap: { [pieceGuid: string]: Piece } = {};
  flatDesign.pieces!.forEach((p) => {
    if (p.guid) pieceMap[p.guid] = p;  // Shallow reference to piece
  });

  // Filter connections - DEFENSIVE FILTER for orphaned connections
  const filteredConnections =
    flatDesign.connections?.filter((connection) => {
      const sourceId = connection.connected.piece.guid;
      const targetId = connection.connecting.piece.guid;
      const sourceExists = pieceMap[sourceId];
      const targetExists = pieceMap[targetId];

      if (!sourceExists) {
        console.warn(
          `[ORIGIN] flattenDesign: Skipping connection ${connection.guid} - source piece ${sourceId} not found`
        );
        return false;  // SKIP - source is orphaned
      }
      if (!targetExists) {
        console.warn(
          `[ORIGIN] flattenDesign: Skipping connection ${connection.guid} - target piece ${targetId} not found`
        );
        return false;  // SKIP - target is orphaned
      }
      return true;
    }) || [];

  // Build cytoscape graph with validated connections
  const cy = cytoscape({
    elements: {
      nodes: flatDesign.pieces!.map((piece) => ({
        data: { id: piece.guid, label: piece.guid },
      })),
      edges: filteredConnections.map((connection, index) => {
        const sourceId = connection.connected.piece.guid;
        const targetId = connection.connecting.piece.guid;
        return {
          data: {
            id: connection.guid,
            source: sourceId,
            target: targetId,
            connectionData: connection,
          },
        };
      }),
    } as any,
    headless: true,
  });

  const components = cy.elements().components();
  // ... continues with component analysis
};
```

**Key Issues & How They're Handled:**
- **Source/target piece not found**: Lines [6652](compose/js/index.ts#L6652-L6656) filter these out (defensive)
- **Piece map is shallow**: Only references pieces from `design.pieces`
- **No circular dependency checks**: Relies on cytoscape graph analysis

---

### 3. **Error Boundary - Layout Error Handling**

**Lines [24404-24480](compose/sketchpad/index.tsx#L24404-L24480):**

```typescript
interface LayoutErrorBoundaryProps {
  children: ReactNode;
  windowId: string;
  onError?: (error: Error, info: React.ErrorInfo) => void;
}

interface LayoutErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

class LayoutErrorBoundary extends React.Component<LayoutErrorBoundaryProps, LayoutErrorBoundaryState> {
  constructor(props: LayoutErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    this.props.onError?.(error, errorInfo);  // Callback for logging
  }

  componentDidUpdate(prevProps: LayoutErrorBoundaryProps) {
    // Reset error when children change (new render attempt)
    if (prevProps.children !== this.props.children && this.state.hasError) {
      this.setState({ hasError: false, error: null });
    }
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-full gap-2 p-4">
          <p className="text-sm text-muted-foreground">Error rendering {this.props.windowId}</p>
          <p className="text-xs text-red-500 font-mono whitespace-pre-wrap max-w-full overflow-auto" data-testid="layout-error-message">
            {this.state.error?.message}
          </p>
          <p className="text-xs text-muted-foreground font-mono whitespace-pre-wrap max-w-full overflow-auto max-h-32" data-testid="layout-error-stack">
            {this.state.error?.stack?.split("\n").slice(0, 5).join("\n")}
          </p>
        </div>
      );
    }
    return this.props.children;
  }
}
```

**Error Handling Flow:**
1. Error in child → `getDerivedStateFromError()` → sets `hasError: true`
2. `componentDidCatch()` → fires optional callback for logging
3. `render()` → shows error message + first 5 stack frames
4. Children change → `componentDidUpdate()` → resets error state (allows retry)

---

### 4. **Scene Window Canvas Architecture**

The complete flow:

```
SketchpadStore.kit(guid)
  ↓ (returns stable CollaborativeKitStore via cache)
PieceMesh component
  ↓ (calls kitStore.getFileBlobUrl(fileGuid))
CollaborativeKitStore.getFileBlobUrl()
  ↓ (tier 1: objectUrls, tier 2: blobs, tier 3: load from provider)
URL string → <LoadedPieceMesh url={blobUrl} />
  ↓
useGLTF(url) or useFBX(url)  ← Three.js loaders
  ↓
scene.scene or geometry rendered in canvas
```

---

### 5. **The "Skipping connection" Warnings - DEFENSIVE FILTERS**

**Not a functional issue.** These are defensive warnings from [lines 6652-6656](compose/js/index.ts#L6652-L6656):
- Only logged when connections reference pieces that don't exist in `design.pieces`
- Filtered out before cytoscape graph analysis
- Common when: pieces are deleted but connections remain (orphaned data)

