type KitFileState = {
  blobs: Map<string, Blob>;
  objectUrls: Map<string, string>;
  providerUrls: Map<string, string>;
  providerFactory?: FileProviderFactory;
  provider?: FileProvider;
  providerKitGuid?: string;
};

type KitBinaryStore = KitStore & {
  readFile?: (path: string) => Promise<Blob | null>;
  writeFile?: (path: string, blob: Blob) => Promise<void>;
  deleteFile?: (path: string) => Promise<void>;
};

const getOrCreateKitFileState = (kitStore: KitStore): KitFileState => {
  const storeWithFiles = kitStore as KitStore & { __composeKitFileState?: KitFileState };
  if (!storeWithFiles.__composeKitFileState) {
    storeWithFiles.__composeKitFileState = {
      blobs: new Map(),
      objectUrls: new Map(),
      providerUrls: new Map(),
    };
  }
