  let cancelled = false;
  let retryTimer: ReturnType<typeof setTimeout> | undefined;
  let retryCount = 0;
  const maxRetries = 3;

  const load = async () => {
    try {
      const url = await kitDataSource.getFileBlobUrl(fileGuid);
      if (!cancelled && url) {
        setBlobUrl(url);
